<?php
require __DIR__.'/_init.php';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$validation=validate_registration($_POST);$errors=$validation['errors'];
 if(!$errors){try{register_student(db(),$_POST);flash('Account created. Sign in to continue.');header('Location: /login.php');exit;}catch(PDOException $error){if($error->getCode()==='23000')$errors[]='That username, email or student number is already registered.';else{error_log((string)$error);$errors[]='Registration could not be completed. Please try again later.';}}catch(Throwable $error){error_log((string)$error);$errors[]='Registration could not be completed. Please try again later.';}}
}
page_start('Create account');?><section class="form-wrap"><div class="eyebrow">STUDENT ACCOUNT</div><h1>Join CampusFlow</h1><p>Use your official student details to get started.</p><?php foreach($errors as $x)echo '<p class="error">'.e($x).'</p>';?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><?php foreach(['full_name'=>'Full name','username'=>'Username','email'=>'Email address','student_number'=>'Student number'] as $n=>$l):?><label><?=$l?><input name="<?=$n?>" value="<?=e(is_string($_POST[$n]??null)?$_POST[$n]:'')?>" required></label><?php endforeach;?><label>Password<input type="password" name="password" minlength="12" maxlength="72" required></label><label>Confirm password<input type="password" name="confirm" minlength="12" maxlength="72" required></label><button class="button">Create account →</button></form></section><?php page_end();?>
